def process_numbers(values):
    result = []
    for value in values:
        if value < 0:
            continue
        squared = value * value
        result.append(squared)
    result.sort(reverse=True)
    unique = []
    for value in result:
        if value in unique:
            continue
        unique.append(value)
    return unique, len(unique)

